CREATE TABLE article (id INTEGER PRIMARY KEY, uuid INTEGER UNIQUE, state INTEGER DEFAULT 1, type INTEGER DEFAULT 0, docName TEXT DEFAULT '', dateAdd INTEGER, dateModif INTEGER, dateArt INTEGER, sort INTEGER DEFAULT 0, isTop INTEGER DEFAULT 0, customField TEXT DEFAULT 'fixture-preserved');
CREATE TABLE cat (id INTEGER PRIMARY KEY, uuid INTEGER UNIQUE, name TEXT, pid INTEGER DEFAULT 0, sort INTEGER DEFAULT 0, sortType INTEGER DEFAULT 0, catType INTEGER DEFAULT 0);
CREATE TABLE cat_article (rid INTEGER REFERENCES cat(uuid), aid INTEGER REFERENCES article(uuid));
CREATE TABLE tag (id INTEGER PRIMARY KEY, uuid INTEGER UNIQUE, name TEXT);
CREATE TABLE tag_article (rid INTEGER, aid INTEGER);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT);
